insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id)
select id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id
from jsonb_to_recordset($json$[{"id":"che-so-137","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A flask holds 8.0 g of CH3OH (32 g mol⁻¹) plus 36 g of water. Molality of methanol is nearest","options":["6.9 m","0.25 m","4.0 m","2.2 m"],"answer_index":0,"explanation":"n(CH3OH) = 0.25 mol in 0.036 kg of water, so m = 0.25/0.036 ≈ 6.9 mol kg⁻¹.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"concentration-terms","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-138","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Mixing 200 mL of 0.60 M H2SO4 with 300 mL of 0.20 M H2SO4, taking volumes as additive, gives a blend of","options":["0.36 M","0.40 M","0.80 M","0.24 M"],"answer_index":0,"explanation":"Moles = 0.12 + 0.06 = 0.18 in 0.50 L, so M = 0.36 mol L⁻¹.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"concentration-terms","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-139","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Henry linked the partial pressure of a dissolved gas to its","options":["mole fraction in the liquid","mass percent alone","molality squared","normal boiling point"],"answer_index":0,"explanation":"One form is $p = K_H x$, with x the mole fraction of the dissolved gas.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"henrys-law","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-140","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"The Henry-law constant $K_H$ is dimensionally a","options":["pressure","volume","molality","entropy"],"answer_index":0,"explanation":"Because $p = K_H x$ and x is dimensionless, $K_H$ has the unit of pressure.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"henrys-law","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-141","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"At a fixed temperature, a larger $K_H$ for a gas means that gas is","options":["more soluble","less soluble","exactly as soluble as every other gas","always immiscible"],"answer_index":1,"explanation":"x = p / $K_H$, so a large constant implies a small dissolved mole fraction.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"henrys-law","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-142","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Soft-drink bottles are packed under extra carbon-dioxide pressure so that","options":["more CO2 remains dissolved until the cap is opened","$K_H$ becomes zero","the drink freezes in the bottle","oxygen is chemically removed"],"answer_index":0,"explanation":"Higher p(CO2) forces a larger x(CO2) in the liquid (Henry’s law).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"henrys-law","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-143","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Deep-sea divers risk decompression sickness because nitrogen","options":["dissolves more at high pressure and bubbles out on a rapid ascent","is insoluble at depth","binds irreversibly to haemoglobin only","forms an azeotrope with blood plasma"],"answer_index":0,"explanation":"High p(N2) loads the blood; a sudden drop in pressure releases bubbles in the tissues.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"henrys-law","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-144","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Warming a solvent generally","options":["raises $K_H$ and lowers gas solubility","lowers $K_H$ and raises gas solubility","leaves gas solubility untouched","ionises the dissolved gas"],"answer_index":0,"explanation":"Gas dissolution is exothermic, so $K_H$ increases and x falls as T rises.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"henrys-law","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-145","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A compact statement of Henry’s law for a sparingly soluble gas is","options":["$p = K_H x$","$p = K_H / x$","$p = x / K_H^2$","$\\pi = CRT$"],"answer_index":0,"explanation":"Partial pressure of the gas is proportional to its mole fraction in the solution.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"henrys-law","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-146","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"At 298 K, $K_H$ for N2 in water is 8.0 × 10⁴ atm. Under 0.80 atm of nitrogen the dissolved mole fraction is","options":["1.0 × 10⁻⁵","8.0 × 10⁻⁴","0.80","1.0 × 10⁻³"],"answer_index":0,"explanation":"x = p / $K_H$ = 0.80 / 8.0 × 10⁴ = 1.0 × 10⁻⁵.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"henrys-law","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-147","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"Two gases have $K_H$ values 2 × 10³ atm and 5 × 10⁴ atm. At the same partial pressure the more soluble gas is the one with","options":["$K_H$ = 2 × 10³ atm","$K_H$ = 5 × 10⁴ atm","equal solubility in both cases","neither gas dissolving"],"answer_index":0,"explanation":"Solubility falls as $K_H$ rises, so the smaller constant marks the more soluble gas.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"henrys-law","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-so-148","chapter_id":"chemistry-solutions","subject_id":"chemistry","stem":"A mountaineer takes up less oxygen at high altitude mainly because","options":["the partial pressure of O2 in the air is lower","$K_H$ of oxygen becomes zero","blood volume instantly doubles","nitrogen is absent from the atmosphere"],"answer_index":0,"explanation":"Henry’s law: dissolved x(O2) tracks p(O2), which falls as total air pressure falls.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"henrys-law","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
